import type { ShaderFragment } from "../../shader/fragment-types.js";
import type { Texture2D } from "../../texture/texture-2d.js";
import type { Mesh } from "../../mesh/mesh.js";
import type { SceneContext } from "../../scene/scene-core.js";
import type { StandardMaterialProps } from "./standard-material.js";

// ─── Feature Flags ──────────────────────────────────────────────────

export const HAS_DIFFUSE_TEXTURE = 1 << 0;
export const HAS_EMISSIVE_TEXTURE = 1 << 1;
export const HAS_BUMP_TEXTURE = 1 << 2;
export const HAS_SPECULAR_TEXTURE = 1 << 3;
export const HAS_AMBIENT_TEXTURE = 1 << 4;
export const HAS_LIGHTMAP_TEXTURE = 1 << 5;
export const HAS_OPACITY_TEXTURE = 1 << 6;
export const LIGHTMAP_USES_UV2 = 1 << 7;
export const AMBIENT_USES_UV2 = 1 << 8;
export const DOUBLE_SIDED = 1 << 9;
export const DIFFUSE_USES_UV2 = 1 << 10;
export const SPECULAR_USES_UV2 = 1 << 11;
export const OPACITY_FROM_RGB = 1 << 12;
export const HAS_REFLECTION_TEXTURE = 1 << 13;
export const DISABLE_LIGHTING = 1 << 14;
export const MATERIAL_ALPHA_BLEND = 1 << 16;
export const HAS_CUBE_REFLECTION = 1 << 17;
export const NO_COLOR_OUTPUT = 1 << 18;
export const HAS_DEPTH_EMISSIVE_TEXTURE = 1 << 19;
export const ESM_SHADOW_OUTPUT = 1 << 20;
export const GEOMETRY_OUTPUT = 1 << 21;
/** Lightmap is used as a baked shadowmap: multiplies the final color instead of adding. */
export const LIGHTMAP_SHADOWMAP = 1 << 15;
/** Lightmap UVs are V-flipped (BJS Texture.uAng === π → uv'=(u, 1-v)). */
export const LIGHTMAP_FLIP_V = 1 << 22;
// Bit 23 is reserved by STD_HAS_UV_TRANSFORM in the lazy
// fragments/std-uv-transform-fragment.ts module.
/** RGBA mesh vertex color drives alpha (Babylon `VERTEXALPHA`). Set only when a
 *  vertex-colour buffer exists and the mesh explicitly opts in via
 *  `mesh.hasVertexAlpha`. Gates the vertex-colour fragment's `alpha *= vColor.a` +
 *  vertex-alpha alpha-test; without it mesh vertex colour is RGB-only. Kept distinct
 *  from `MATERIAL_ALPHA_BLEND`, which is also used by material and thin-instance
 *  alpha, so those sources never create a redundant vertex-colour shader variant. */
export const VERTEX_ALPHA = 1 << 24;
// Bit 25 is reserved by HAS_STD_PLUGINS in the opt-in std-plugin-bridge module.
/** Mesh uses skeletal skinning. Enabled through the Standard mesh-feature subpath. */
export const HAS_SKELETON = 1 << 26;
/** Skinned mesh has a second JOINTS/WEIGHTS set. */
export const HAS_SKELETON_8 = 1 << 27;
// Bit 28 is rect-area-light-local (fragments/rect-area-light-fragment.ts).
// Bit 29 is rect-area-light-emission-local (fragments/rect-area-light-emission-fragment.ts).
// Bit 30 is reserved by mesh/opacity (feature-local constant).
// Bit 31 is reserved by STD_HAS_PARALLAX_OCCLUSION in the opt-in
// fragments/std-parallax-occlusion-fragment.ts module.

// ─── Standard Scene Features ───────────────────────────────────────

/** Scene contributes Standard fog WGSL. Kept separate from material/mesh bits. */
export const STD_SCENE_FOG = 1 << 0;
/** @internal Nullable scalar shader-source transport, installed by scene-lighting enablers only. */
export let _stdSceneLightingSource: ((source: string | undefined) => string | undefined) | null = null;
/** @internal No scene or branch-gating shader context crosses this seam. */
export function _installStandardLightingSource(): void {
    _stdSceneLightingSource = (source) => source;
}

// ─── Standard Material Extension Registry ───────────────────────────

/** Bind-ordering phase for StdExt textures (alphabetical by id within phase, matching composer). */
export type StdExtPhase = "mesh";

/** Unified extension for Standard material. Each fragment module exports one.
 *  Fragments register via `_registerStdExt(ext)` at dynamic-import sites. */
export interface StdExt {
    /** @internal */
    readonly _id: string;
    /** @internal */
    readonly _phase: StdExtPhase;
    /** @internal Feature bit this ext gates on. */
    readonly _feature: number;
    /** @internal Contribute material feature bits for `mat` (including this ext's own
     *  sub-bits, e.g. UV-set or mode selectors). Returns 0 when the material does not
     *  use the feature. Only registered exts are consulted, so an opt-in setter is the
     *  sole way these bits can ever be set — which is what keeps the detection code
     *  (and the fragment it gates) out of the always-loaded core. */
    _detect?(mat: StandardMaterialProps): number;
    /** @internal Effective Standard feature bits contributed by one mesh. */
    _meshFeatures?(meshFeatures: number, material?: StandardMaterialProps): number;
    /** @internal */
    _frag(features: number, meshFeatures?: number, material?: StandardMaterialProps): ShaderFragment;
    /** @internal Push group-1 bind entries starting at binding `b`; return new b.
     *  Register binding-owned releases in `disposers`; auxiliary owners survive main-material changes. */
    _bind?(mat: StandardMaterialProps, entries: GPUBindGroupEntry[], b: number, mesh?: Mesh, scene?: SceneContext, disposers?: (() => void)[], auxiliary?: boolean): number;
    /** @internal Bind feature-owned vertex buffers and return the next slot. */
    _bindVertexBuffers?(mesh: Mesh, pass: GPURenderPassEncoder | GPURenderBundleEncoder, slot: number): number;
    /** @internal Enumerate textures for acquire/release. */
    _textures?(mat: StandardMaterialProps, out: Texture2D[]): void;
    /** @internal Write extension-owned material UBO state. */
    _writeUbo?(data: Float32Array, mat: StandardMaterialProps): void;
}

export interface ShadowLightSlotLite {
    lightIndex: number;
    shadowType: "esm" | "pcf";
}

/** @internal Optional material-specific shader identity, installed by opt-in extensions. */
export let _stdMaterialVariantKey: ((material: StandardMaterialProps) => string) | null = null;

/** @internal Install material-variant cache keying without adding an extension scan to the core. */
export function _installStdMaterialVariantKey(resolve: (material: StandardMaterialProps) => string): void {
    _stdMaterialVariantKey = resolve;
}

// Lazy-init: avoids a module-level `new Map()` that defeats tree-shaking for
// consumers importing flags/registry symbols without using extensions.
// See GUIDANCE.md §4 ("Zero module-level side effects").
let _stdExts: Map<string, StdExt> | null = null;
let _stdExtsSorted: readonly StdExt[] | null = null;

export function _registerStdExt(ext: StdExt): void {
    (_stdExts ??= new Map()).set(ext._id, ext);
    _stdExtsSorted = null;
}

export function _getStdExts(): ReadonlyMap<string, StdExt> {
    return (_stdExts ??= new Map());
}

export function _getStdExtsSorted(): readonly StdExt[] {
    if (!_stdExtsSorted) {
        const map = _stdExts;
        _stdExtsSorted = map ? Array.from(map.values()).sort((a, b) => a._id.localeCompare(b._id)) : [];
    }
    return _stdExtsSorted;
}

/** Derived: mesh needs UV attribute (any texture present). */
export const NEEDS_UV = HAS_DIFFUSE_TEXTURE | HAS_EMISSIVE_TEXTURE | HAS_BUMP_TEXTURE | HAS_SPECULAR_TEXTURE | HAS_AMBIENT_TEXTURE | HAS_LIGHTMAP_TEXTURE | HAS_OPACITY_TEXTURE;

/** Derived: mesh needs UV2 attribute. */
export const NEEDS_UV2 = LIGHTMAP_USES_UV2 | AMBIENT_USES_UV2 | DIFFUSE_USES_UV2 | SPECULAR_USES_UV2;
